"""Manual original-pixel RCC panel reference with source ownership limits."""
import json
from pathlib import Path
r=Path('benchmarks/dense50');n='PMC13582412.1';s=json.loads((r/'sources'/f'{n}.json').read_text());assets=json.loads((r/'figure-assets'/f'{n}.json').read_text());seg={x['segment_id']:x['text'] for x in s['segments']}
def ev(sid,q):assert q in seg[sid];return dict(segment_id=sid,quote=q)
def tag(value,basis,cue=None,evidence=None,raw=None):return dict(value=value,as_documented=raw,basis=basis,visual_cue=cue,evidence=evidence or [],certainty='clear')
rows=[
('A','Pink/purple cellular tissue with broad closely packed nests and sheets.','Upper-left panel A shows a broad pink/purple microscopic field. Many round/oval blue-purple nuclei occupy pale-pink cellular profiles with visible outlines, interrupted by paler rounded areas and narrow red/pink vessel-like structures. No arrows or quantitative overlays are present.','The tumors predominantly exhibited solid/nested and sheet-like architecture composed of eosinophilic tumor cells with pronounced cellular membrane and occasional perinuclear clearing, reminiscent of chromophobe RCC (A).','Authors describe eosinophilic nested/sheet-like morphology with occasional perinuclear clearing and chromophobe-like resemblance. The physical specimen owner is unresolved; this is not proof of each patient’s individual panel morphology.'),
('B','Closer cellular field with round blue-purple nuclei and pink cytoplasm.','Top-middle panel B shows closely packed pale-pink and purple cellular profiles with round dark nuclei and some conspicuous darker central nuclear dots. A small red/pink vessel-like cluster lies toward the upper-left. No arrows, counts or magnification labels are printed.','However, the tumor cells consistently had round nuclei with smooth nuclear membrane and prominent nucleoli (A, B). Mitotic figures were frequent (B), and tumor necrosis was also present (C).','Authors identify round smooth nuclei, prominent nucleoli and frequent mitotic figures in B. No mitotic count is estimated from this field, and no individual patient is assigned.'),
('C','Irregular pale-pink central region surrounded by densely cellular purple tissue.','Top-right panel C contains a broad irregular pale-pink central area with relatively few dark nuclear profiles. Purple cellular tissue surrounds it, and white clefts cross parts of the boundary. Small red/pink areas occur toward the lower-right. No scale, arrows or percentage labels are printed.','Mitotic figures were frequent (B), and tumor necrosis was also present (C).','Authors identify necrosis in C. The source’s pooled five-percent necrosis claim is not measured from pixels or assigned separately to either patient.'),
('D','Loose purple cellular nests with pale spaces and black/green arrows.','Second-row left panel D shows purple/pink cellular groups interrupted by broad pale spaces. Three black arrows point to larger darker cellular profiles, while four green arrows point toward paler or clear-centered profiles. Red/pink spots occur at the right edge. No quantitative label appears.','Some areas showed tumor cells forming loose nests and cords in a background of light-pink amorphous/mucoid material (D). In these loosely formed areas with amorphous/mucoid material, binucleated tumor cells with rhabdoid morphology (black arrows; D) and vacuolated tumor cells were seen (green arrows; D).','The authors map black arrows to binucleated rhabdoid cells and green arrows to vacuolated cells within loose nests/cords. Their occurrence in each separate tumor remains unresolved.'),
('E','Elongated cellular groups and pale channels with a red arrow.','Second-row middle panel E shows purple/pink cellular groups separated by elongated white/pale channels. One red arrow near the center points to a round cellular profile containing a smaller pale circular internal area. No size ruler or count is present.','The tumor cells also occasionally formed pseudotubular and pseudoglandular spaces, with some tumor cells with pseudonuclear inclusions (red arrow; E).','Authors identify pseudotubular/pseudoglandular spaces and a pseudonuclear inclusion at the red arrow. This is source interpretation of an unresolved-owner specimen, not a new patient diagnosis.'),
('F','Rounded cellular groups within broad pale-pink stromal bands.','Second-row right panel F shows rounded/irregular purple cellular groups distributed through broad pale-pink material. A prominent pale-pink band passes through the central field with smaller white/pale spaces around the groups. No arrows or text measurements are printed.','Prominent hyalinized stroma (F) and psammomatous calcification (G) were focally seen.','Authors describe prominent hyalinized stroma in F. Its focal presence is not automatically asserted for both patients.'),
('G','Purple tumor-like nests and pink bands with an arrowed dark rounded focus.','Third-row left panel G shows purple cellular groups separated by pink bands. A green arrow near the lower-left of center points to a small dark rounded ring-like focus. No calcification measurement, scale or numerical label appears.','Prominent hyalinized stroma (F) and psammomatous calcification (G) were focally seen.','Authors identify focal psammomatous calcification in G. Pixel appearance does not establish patient ownership or a separate calcium measurement.'),
('H','Large pale-purple cellular profiles with blue arrows to small dark cytoplasmic foci.','Third-row middle panel H shows larger pale-pink/purple cellular profiles with round blue nuclei, intervening white spaces and several small darker blue-purple granule-like foci. Multiple blue arrows point toward these small foci within or adjacent to cellular profiles. No antigen, count or scale is printed.','Lastly, the tumor cells with “blue granules” reminiscent of ESC RCC were also identified (blue arrows; H).','Authors describe blue granules reminiscent of ESC RCC at the blue arrows. This resemblance is a differential morphology observation, not an ESC RCC diagnosis assigned to a patient.'),
('I','Broad brown cellular-outline staining with pale-blue nuclei.','Third-row right panel I shows densely distributed brown staining following many cellular outlines and intervening cytoplasmic areas, with numerous pale-blue nuclear profiles. White branching bands separate groups of cells. No marker name, positivity percentage or intensity legend is printed.','By immunohistochemistry, both tumors were positive for PAX8 (diffuse) and CD117 (diffuse; I) and negative for vimentin (J), similar to chromophobe RCC.','The caption maps I to diffuse CD117 expression. Both tumors’ results are explicit in text, but the specific photographed specimen in I is not identified as both patients or as either one.'),
('J','Predominantly pale-blue cellular tissue with brown staining in narrow background bands.','Bottom-left panel J is predominantly pale-blue cellular tissue with brown staining concentrated in thin branching background bands and scattered smaller areas. Much of the cellular field lacks conspicuous brown coloration. No marker label or scoring threshold is printed.','By immunohistochemistry, both tumors were positive for PAX8 (diffuse) and CD117 (diffuse; I) and negative for vimentin (J), similar to chromophobe RCC.','Authors call the tumor vimentin-negative in J. Visible background brown staining is described separately and does not reverse that source claim or establish an individual owner.'),
('K','Very pale-blue microscopic cellular field with scant brown coloration.','Bottom-middle panel K contains pale-blue nuclear profiles distributed through a very light background, with only sparse faint brown coloration. No antigen label, percentage, arrow or calibrated scale is printed.','However, the tumors were negative for CK7 (K).','The caption maps K to CK7-negative tumor staining; exact specimen ownership remains unresolved.'),
('L','Strong diffuse brown cellular-outline staining with pale-blue nuclei.','Bottom-right panel L contains strong brown staining around numerous pale-blue nuclear profiles. White branching bands divide dense groups, and many cellular centers remain pale. No CK20 text, percentage or ruler is printed within the field.','The tumors were both positive for CK20, with tumor #2 showing diffuse CK20 expression (L) and tumor #1 showing focal CK20 expression','The caption explicitly maps L to tumor2 diffuse CK20 expression. Article tumor2 is the right renal tumor; this is patient2 specimen evidence. The >90% result comes from the article, not a pixel-derived count.')]
panels=[];assign=[]
for letter,general,detail,claim,meaning in rows:
 ce=ev('b00028',claim);owner=letter=='L';lim=['No stain name, magnification or calibrated scale is printed in the panel. No numerical cell count, mitotic rate or necrosis percentage is estimated.']
 if not owner:lim.append('Physical specimen ownership between the two local patients is unresolved; pooled caption wording does not mean this panel depicts both patients.')
 body=[tag('right kidney','article',evidence=[ev('b00011','Patient #2 was a 55-year-old male'),ev('b00011','a right renal mass (13 cm in greatest dimension)'),ev('b00013','Tumor #2 showed diffuse (> 90%) CK20 expression (Fig. Fig. 1L)')],raw='right renal mass')] if owner else [tag('kidney','article',evidence=[ev('b00006','two cases of MTOR-mutated eosinophilic RCC with loss of chromosome 1'),ev('b00010','left renal mass'),ev('b00011','right renal mass'),ev('b00012','The two tumors showed similar morphology.')],raw=None)]
 sub=[tag('immunohistochemistry','caption',evidence=[ev('b00028','By immunohistochemistry')],raw='immunohistochemistry')] if letter in 'IJKL' else []
 significance=dict(statement=meaning,role='differential_diagnosis' if letter in ['A','H'] else 'diagnostic_evidence',clinical_fact_status='unreviewed_annotation',basis='caption',visual_cue=None,evidence=[ce],certainty='clear')
 if letter=='C':significance['evidence'].append(ev('b00012','Tumor necrosis was also focally (5%) present (Fig. 1C).'))
 if owner:significance['evidence'] += [ev('b00013','Tumor #2 showed diffuse (> 90%) CK20 expression (Fig. Fig. 1L)'),ev('b00011','a right renal mass (13 cm in greatest dimension)')]
 panels.append(dict(panel=letter,general_description=general,detailed_description=detail,image_kind='microscopy',has_chart=False,charts=[],imaging_modalities=[tag('light_microscopy','pixels',cue='Colored magnified tissue field with cellular and nuclear profiles.')],imaging_submodalities=sub,medical_domains=[tag('pathology','article',evidence=[ev('b00008','slides were reviewed by two expert genitourinary pathologists')]),tag('oncology','article',evidence=[ev('b00006','two cases of MTOR-mutated eosinophilic RCC with loss of chromosome 1')])],body_parts=body,mentioned_categories=[],pixel_observations=[general,'Panel label '+letter+' is visible. No quantitative overlay is printed.'],caption_claims=[tag(claim,'caption',evidence=[ce],raw=claim)],clinical_significance=[significance],diagram_relations=[],limitations=lim))
 assign.append(dict(panel=letter,patient_ids=['p2'] if owner else [],scope='individual' if owner else 'unresolved',subject='patient_specimen' if owner else 'unresolved',evidence=[ce,ev('b00011','Patient #2 was a 55-year-old male'),ev('b00013','Tumor #2 showed diffuse (> 90%) CK20 expression (Fig. Fig. 1L)')] if owner else [ce],rationale='Caption explicitly assigns L to tumor2, tied to Patient2 and the right renal mass in the case paragraph; microscopic tissue is patient_specimen.' if owner else 'Caption describes tumors collectively without identifying this physical panel specimen; both-patient attribution would be unsupported.'))
limits=['A–K unresolved in physical patient/specimen ownership; only L explicitly identifies tumor2.','No per-panel H&E stain or magnification is inferred from general methods, colors or field size.','Rare morphology and pooled maxima are not individually assigned from these pixels.']
manifest=next(x for x in assets['figures'] if x['figure_id']=='Fig1');visual=dict(figure_id='Fig1',general_description='Twelve-panel renal tumor microscopy and immunohistochemical composite.',detailed_description='Four rows of three panels on a white background with thin dark panel borders and bold visible letters A–L. Rows are A/B/C, D/E/F, G/H/I, J/K/L. A–H show pink/purple cellular tissue; I and L have broad brown staining, J has brown background bands and K is predominantly pale-blue. Colored arrows appear in D/E/G/H. No rulers, magnification labels, numeric scores or antigen labels are printed within the fields.',panels=panels,limitations=limits)
x=dict(format='dense-figure-reference/1',article_id=n,source_text_sha256=s['text_sha256'],figures=[dict(figure_id='Fig1',status='inspected',assets=[dict(url=z['url'],sha256=z['sha256']) for z in manifest['assets']],analysis=dict(visual=visual,attribution=dict(figure_id='Fig1',assignments=assign,limitations=limits)),limitations=limits)])
(r/'visual-submissions'/f'{n}.json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
